<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paddock Lab Legacy</title><style>body{font:15px system-ui;background:#0d1117;color:#e6edf3;margin:0;padding:2rem}main{max-width:1100px;margin:auto}.muted,pre{color:#8b949e}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem;margin-top:2rem}.card{border:1px solid #30363d;border-radius:10px;padding:1rem;background:#161b22}.pass{border-color:#238636}.fail{border-color:#da3633}pre{white-space:pre-wrap}a{color:#58a6ff}</style></head><body><main><h1>Paddock Lab Legacy</h1><p class="muted">Laravel 9 · PHP 8.0–8.2 · live compatibility probes</p><div id="checks" class="grid"><div class="card">Running checks…</div></div></main><script src="/build/app.js" type="module"></script><script>fetch('/paddock/api/smoke').then(async r=>({data:await r.json(),header:r.headers.get('x-paddock-lab')})).then(({data,header})=>{if(!header){data.checks.http.status='fail';data.checks.http.details+='; X-Paddock-Lab header missing'}else data.checks.http.details+=`; nginx header ${header}`;document.querySelector('#checks').innerHTML=Object.values(data.checks).map(c=>`<section class="card ${c.status}"><strong>${c.label}</strong><p>${c.status.toUpperCase()} · ${c.duration_ms} ms${c.version?' · '+c.version:''}</p><pre>${c.details}</pre>${c.url?`<a href="${c.url}">Open dashboard</a>`:''}</section>`).join('')}).catch(e=>document.querySelector('#checks').innerHTML=`<section class="card fail">${e}</section>`)</script></body></html>
